/*
 * File:      menu.h
 * Generated: 2026-10-22 14:00:00 -04:00
 * Project:   RTLNet Nexys Video firmware, hierarchical CLI (MenuBuilder
 *            extended per cli/MenuBuilder_hierarchical.md)
 * Purpose:   Public API, types and limits of the hierarchical menu engine
 *            (menu.c): command modes and prompts, the command definition
 *            table produced by cli/gen_menu.py from cli/cli_commands.txt,
 *            the callback context, and the character-level line editor
 *            entry point.
 *
 * The engine is portable ISO C11 with no library dependency beyond the
 * freestanding headers <stdint.h> and <stddef.h>, so it builds unchanged
 * for the MicroBlaze target (no C library) and for the desktop harness.
 * All output goes through the MenuIo write hook given to Menu_Init().
 *
 * Header holds signatures, types and contract prose; menu.c holds the
 * per-function commentary.
 */
#ifndef MENU_H
#define MENU_H

#include <stddef.h>   /* size_t */
#include <stdint.h>   /* uint8_t */

/* Limits (static storage only; no heap). */
#define MENU_MAX_TOKENS      16u   /* tokens per typed command line */
#define MENU_MAX_SYNTAX_TOKENS 14u /* tokens per command syntax */
#define MENU_MAX_ARGS        14u   /* parameter values passed to a callback */
#define MENU_MAX_TOKEN_TEXT  24u   /* characters of one syntax token, NUL included */
#define MENU_LINE_MAX        160u  /* characters of one input line */
#define MENU_HISTORY_DEPTH   8u    /* remembered command lines */
#define MENU_MAX_COMMANDS    128u  /* table entries plus built-ins */

/* Command modes, network-switch style. The set is fixed by the input format
 * (MenuBuilder_hierarchical.md section 3); gen_menu.py maps the .txt mode
 * names onto these values. */
typedef enum {
    MENU_MODE_EXEC = 0,      /* rtlnet>                user exec */
    MENU_MODE_PRIV,          /* rtlnet#                privileged exec */
    MENU_MODE_CONFIG,        /* rtlnet(config)#        global configuration */
    MENU_MODE_CONFIG_IF,     /* rtlnet(config-if)#     interface configuration */
    MENU_MODE_CONFIG_DHCP,   /* rtlnet(config-dhcp)#   DHCP client configuration */
    MENU_MODE_CONFIG_SOCK,   /* rtlnet(config-sock)#   UDP socket configuration */
    MENU_MODE_COUNT,
    MENU_MODE_NONE = 0xFF    /* "no mode change" in MenuCommandDef.enter_mode */
} MenuMode;

/* Syntax token classes. */
typedef enum {
    MENU_TOKEN_KEYWORD = 0,      /* plain word, case-insensitive, unique prefix accepted */
    MENU_TOKEN_REQUIRED_PARAM,   /* [NAME] */
    MENU_TOKEN_OPTIONAL_PARAM    /* {NAME}, only after every required token */
} MenuTokenType;

/* What a callback receives: the parameter values in syntax order. */
typedef struct {
    int         argc;
    const char *argv[MENU_MAX_ARGS];
    MenuMode    mode;            /* mode the command was typed in */
} MenuCommandContext;

/* Callback: 0 = success; nonzero = failure (for a mode-entry command the
 * mode is then not changed). */
typedef int (*MenuCallback)(const MenuCommandContext *ctx);

/* One command (FUNCTION:MODE:COMMAND:DESCRIPTION) or mode-entry command
 * (MODE-ENTER line). Commands of MENU_MODE_EXEC are also available in
 * MENU_MODE_PRIV. */
typedef struct {
    const char  *function_name;  /* FUNCTION field ("-" for none) */
    MenuMode     mode;           /* mode the command belongs to */
    const char  *syntax;         /* COMMAND field */
    const char  *description;    /* DESCRIPTION field */
    MenuCallback callback;       /* may be NULL only for a mode-entry command */
    MenuMode     enter_mode;     /* MENU_MODE_NONE, or the mode entered on success */
} MenuCommandDef;

/* One mode: prompt and the mode `exit` returns to. */
typedef struct {
    MenuMode    mode;
    const char *name;            /* exec, priv, config, ... */
    const char *prompt;          /* rtlnet>, rtlnet#, ... */
    MenuMode    parent;          /* MENU_MODE_NONE for the root */
    const char *description;
} MenuModeDef;

/* Help text of an intermediate keyword shared by several commands
 * (KEYWORD:MODE:PATH:DESCRIPTION). */
typedef struct {
    MenuMode    mode;
    const char *path;            /* keyword path, e.g. "SHOW" or "NO IP" */
    const char *description;
} MenuKeywordDef;

/* Output hook: writes n characters; "\n" is the line end (the console layer
 * converts it for the terminal). */
typedef struct {
    void (*write)(const char *s, size_t n);
} MenuIo;

/* Generated tables (cli/menu_table.c from cli/cli_commands.txt). */
extern const MenuCommandDef g_menu_commands[];
extern const size_t         g_menu_command_count;
extern const MenuModeDef    g_menu_modes[];
extern const size_t         g_menu_mode_count;
extern const MenuKeywordDef g_menu_keywords[];
extern const size_t         g_menu_keyword_count;

/* Engine API. */
int      Menu_Init(const MenuIo *io);
int      Menu_ProcessLine(const char *line);
void     Menu_InputChar(int c);
void     Menu_PrintHelp(void);
void     Menu_PrintPrompt(void);
void     Menu_Redisplay(void);
void     Menu_SetMode(MenuMode mode);
MenuMode Menu_GetMode(void);
const char *Menu_ModeName(MenuMode mode);
void     Menu_Write(const char *s);

#endif /* MENU_H */
